import { CliParseError } from './errors.mjs';
import { isNegativeNumberToken, parsePythonInt } from './pythonInt.mjs';

const OPTION_SPECS = [
  { flag: '--a', key: 'a', metavar: 'A', type: 'int' },
  { flag: '--b', key: 'b', metavar: 'B', type: 'int' },
  { flag: '--c', key: 'c', metavar: 'C', type: 'string' },
];

const OPTION_INDEX = new Map(OPTION_SPECS.map((spec) => [spec.flag, spec]));

export function getProgramName(scriptPath) {
  if (!scriptPath) {
    return 'test8.mjs';
  }

  const normalized = scriptPath.replace(/\\/g, '/');
  const parts = normalized.split('/');
  return parts[parts.length - 1] || 'test8.mjs';
}

export function createUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

export function createHelp(programName) {
  return `${createUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C`;
}

export function formatCliError(programName, message) {
  return `${createUsage(programName)}\n${programName}: error: ${message}\n`;
}

export function parseCommandLine(argv, programName = getProgramName(process.argv[1])) {
  const values = {
    a: undefined,
    b: undefined,
    c: undefined,
  };
  const unknownTokens = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return {
        helpRequested: true,
        programName,
      };
    }

    const { optionToken, inlineValue } = splitOptionToken(token);
    const spec = OPTION_INDEX.get(optionToken);

    if (!spec) {
      unknownTokens.push(token);
      continue;
    }

    const valueToken =
      inlineValue !== null ? inlineValue : consumeSeparateValue(argv, index, spec.flag);

    if (inlineValue === null) {
      index += 1;
    }

    values[spec.key] = parseValue(spec, valueToken);
  }

  const missingFlags = OPTION_SPECS.filter((spec) => values[spec.key] === undefined).map(
    (spec) => spec.flag,
  );

  if (missingFlags.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missingFlags.join(', ')}`);
  }

  if (unknownTokens.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${unknownTokens.join(' ')}`);
  }

  return {
    helpRequested: false,
    programName,
    ...values,
  };
}

function splitOptionToken(token) {
  const equalsIndex = token.indexOf('=');

  if (equalsIndex === -1) {
    return { optionToken: token, inlineValue: null };
  }

  return {
    optionToken: token.slice(0, equalsIndex),
    inlineValue: token.slice(equalsIndex + 1),
  };
}

function consumeSeparateValue(argv, optionIndex, optionName) {
  const valueToken = argv[optionIndex + 1];

  if (valueToken === undefined || isMissingValueToken(valueToken)) {
    throw new CliParseError(`argument ${optionName}: expected one argument`);
  }

  return valueToken;
}

function isMissingValueToken(token) {
  if (token === '--') {
    return true;
  }

  return token.startsWith('-') && !isNegativeNumberToken(token);
}

function parseValue(spec, token) {
  if (spec.type === 'int') {
    return parsePythonInt(token, spec.flag);
  }

  return token;
}

