export function main(argv = process.argv.slice(2)) {
  const programName = getProgramName(process.argv[1]);

  try {
    const args = parseCommandLine(argv, programName);

    if (args.helpRequested) {
      process.stdout.write(`${createHelp(programName)}\n`);
      return 0;
    }

    const format1 = buildInt8ul(args.a);
    const format2 = buildInt8ul(args.b);
    const length = countPythonStringLength(args.c);
