    return 0;
  } catch (error) {
    if (error instanceof CliParseError) {
      process.stderr.write(formatCliError(programName, error.message));
      return error.exitCode;
    }

    if (isConstructBuildError(error)) {
      process.stderr.write(`${formatConstructBuildError(error)}\n`);
      return error.exitCode;
    }

    throw error;
  }
}

