  const hasSingleQuote = buffer.includes(0x27);
  const hasDoubleQuote = buffer.includes(0x22);

  if (hasSingleQuote && !hasDoubleQuote) {
    return '"';
  }

  return "'";
}

function renderByte(value, quote) {
  if (value === 0x5c) {
    return '\\\\';
  }

  if (value === 0x09) {
